; Huffman-compressed text group(s): $36
; Text $06C0: Poor Taloon!'<4F>Because his cave opened a pathway between countries,the monsters are after him.
; Text $06C1: One,Two,One,Two,La,La,La...
; Text $06C2: I heard the monsters destroyed the Hero who was to save the world.'<4F>Don't worry,we will save the world.
; Text $06C3: We have nothing to fear.
; Text $06C4: These people visit many places.I can make lots of money by following them.
; Text $06C5: It's hopeless!'<4F>I hear the Hero who was to defeat the Ruler of Evil was destroyed.
; Text $06C6: There's a legend in this country.'<4F>When a great evil arises,a Hero will emerge.
; Text $06C7: This is King Branca's chamber.
; Text $06C8: A wedding is being held at the Castle.
; Text $06C9: If you want to go to the wedding,enter the Coliseum through the small doors on the left or right.
; Text $06CA: Long ago,black clouds drifted into the eastern sky.'<4F>Soon after,I heard the Hero who was to save the world died.
; Text $06CB: I'm here because I heard this shop has many unique goods.
; Text $06CC: This is the Coliseum,where the wedding is.
; Text $06CD: The King's chamber is upstairs.
; Text $06CE: I didn't know the Princess had someone she loved.'<4F>It's nice she could marry him.
; Text $06CF: Far east of Branca there is a big desert.'<4F>Even ships are for sale at the port town south of the desert.
; Text $06D0: Somewhere in this world the Ruler of Evil is about to resurrect.
; Text $06D1: I hear the man named Taloon crossed the eastern desert.'<4F>Even if he did it for wealth,I still think he's brave.
; Text $06D2: This is the Castle Kitchen.
; Text $06D3: Our King is at the wedding.
; Text $06D4: According to old books,the Ruler of Evil seemed to have been the being who achieved the highest level of evolution.'<4F>Fearing his overwhelming power,the good forces in this world imprisoned him.
; Text $06D5: This is the dressing room of the King and the Princess.
; Text $06D6: It's always nice to watch weddings.
; Text $06D7: Oh,now I want to get married too!
; Text $06D8: How long does this wedding last?
; Text $06D9: Oh,come on! Just grab her and kiss her!
; Text $06DA: Whinny'
; Text $06DB: He,He,He! I'll eat them,and you'll be next.
; Text $06DC: Welcome to Aneaux,a spa town.
; Text $06DD: Have you seen the armor kept at the House of Healing? Isn't it impressive?
; Text $06DE: Yes,I feel relieved.My son brought me to this spa.
; Text $06DF: The Port Town of Konenber is far south of here.
