; Huffman-compressed text group(s): $37
; Text $06E0: Ruvas the Soldier was a great man.'<4F>Many years ago,when monsters terrorized this town,he fought with them...'<4F>and perished along with the last monster in the final battle.
; Text $06E1: Hmm...I think that Ruvas's Armor is fake.'<4F>Someone switched the real armor with the fake?
; Text $06E2: A ghost appears at the graveyard.Do you believe it?
; Text $06E3: The spa waters here are known to make your skin silky.'<4F>Should I try to make my skin even more beautiful?
; Text $06E4: Well,I just wanted to do something nice for the old geezer,so I brought him here.
; Text $06E5: This is Konenber,a port town.
; Text $06E6: The locked room over there must remain closed.
; Text $06E7: Some fell in despair after the monsters sank the ships....I pity them.
; Text $06E8: Deep in the mountains,north of faraway Branca,they just discovered a village rampaged by monsters.'<4F>The people of Santeem,across the sea,vanished without a trace....'<4F>Do these events have some connection to the rumor the Ruler of Evil will resurrect?
; Text $06E9: Move! Please! You are blocking the dockhand's way.
; Text $06EA: Whose ship is this? Looks quite expensive.
; Text $06EB: Wow! What a big ship!
; Text $06EC: A new ship is useless here.You can't sail out of the harbor because the lighthouse is causing havoc.
; Text $06ED: What? Who's the owner of the ship? Go ask my boss!
; Text $06EE: This is a wharf.We're building a new ship.
; Text $06EF: Taloon said he wanted to go south.'<4F>A sailing expert who has a priceless map lives on a southern continent,in a town called Mintos.
; Text $06F0: When can we sail? The cargo will rot soon.
; Text $06F1: Children are always restless!
; Text $06F2: Hurray! It's a ship! Hurray!
; Text $06F3: I'm frustrated because we can't sail.'<4F>If I were a lot stronger,I'd go wipe out the monsters in the eastern lighthouse....
; Text $06F4: I'm the captain of this ship.I want to sail too.'<4F>However,when a ship leaves the shore,the lighthouse shines eerily and makes the sea rage violently.
; Text $06F5: The last ship to leave here was sailing south.They say the Princess of Santeem was on board.'<4F>I bet she was a beauty.
; Text $06F6: Welcome! Stay here!
; Text $06F7: We still have some good rooms available today.
; Text $06F8: This is the Town of Mintos.'<4F>Old Howden,a mentor for aspiring merchants,lives here.
; Text $06F9: Old Howden was an adventurer.'<4F>The many treasures he discovered enabled him to start a business.Now he's tremendously successful.
; Text $06FA: Gurz...Gurz...
; Text $06FB: I'm a merchant's daughter.I have to study business.
; Text $06FC: Old Howden's stories are quite instructive.'<4F>Don't sell things,sell hearts! I'm struck with admiration by this idea!
; Text $06FD: I took Old Howden's quiz too....'<4F>I still don't have the answer.Oh,I want that Treasure Map!
; Text $06FE: I became gravely ill when I was little.'<4F>My grandfather from Soretta brought me a root of Padequia.It cured me completely.
; Text $06FF: Aren't we good children? We're helping with the housework.
