; Huffman-compressed text group(s): $38
; Text $0700: <4E>Cristo:'Oooh...Oooh...'
; Text $0701: Welcome to Soretta Castle! Please come in.
; Text $0702: <4E>No response...<44>Seems to be just a scarecrow.
; Text $0703: You came from Mintos? My married daughter lives there.
; Text $0704: This is King Soretta's chamber.
; Text $0705: Hi,it's you again! Don't you remember? We met at Branca Castle.'<4F>Sorry we couldn't let you join us then because we were full.
; Text $0706: I'm traveling to save the world from the hands of the Ruler of Evil.
; Text $0707: Princess Alena,back there,joined us.'<4F>We've accompanied her to this cave.
; Text $0708: A short while ago,we caught a suspicious,traveling soldier sneaking into the Castle.'<4F>As soon as his interrogation by the counselor is over,he'll be taken to the King.'<4F>His life will probably be over then.Unlucky man....
; Text $0709: <4E><44>'I know the mechanism to open the entrance is at the bottom of a treasure chest,but...Hmm...'
; Text $070A: You defeated Keeleon? Oh,no! Spare me,please!'<4F>The abominable Balzack is in Santeem Castle! I've given you valuable information,haven't I?
; Text $070B: Kiii! We monsters have taken over Santeem Castle!'<4F>The King of this Castle is Balzack!
; Text $070C: That Balzack! Who does he think he is?'<4F>I wouldn't work for him if it wasn't for Necrosaro's order.KiKii!
; Text $070D: I'm not a bad Slime.I came to see my friend,Meena the cat,because I was concerned about her.'<4F>Meena says the King of Santeem had a strange power.'<4F>She says you should talk to a person in Surene who can tell you more.
; Text $070E: Meow,Meow,Meow!
; Text $070F: Legend was that Santeem's former Kings could foretell the future.'<4F>If that's true,the present King may have that same power.
; Text $0710: My grandfather was the tutor of the King of Santeem.'<4F>He's very proud of that.
; Text $0711: This happened when the King was still a child.'<4F>He woke up in the middle of the night and begged me...'<4F>to put up a signpost to help his daughter who was in trouble.'<4F>Let me see...where did I put it up?...what did it say?...I can't remember.
; Text $0712: Oh,Edgar's daughter! It's me,Orin!'<4F>Listen to me.'<4F>The object of your revenge,Balzack,seems to be under the protection of Necrosaro.'<4F>By using the Secret of Evolution,Necrosaro intends to make the monsters even more powerful.'<4F>We have to destroy the Secret of Evolution before he succeeds!'<4F>Your late father,Edgar,would have wished this also.
; Text $0713: I'm Orin.I was a pupil of Edgar the alchemist.'<4F>I wonder how Edgar's daughters are doing....
; Text $0714: I found Orin as I was escaping from Keeleon Castle.'<4F>I thought he was dead from his terrible wounds.'<4F>When the soldiers closed in on me,he suddenly rose and fought....'<4F>I owe him my life! Blush...
; Text $0715: This is Seaside Village.
; Text $0716: Our ancestors were pirates.'<4F>Many years ago they settled on the land...'<4F>leaving the treasures they'd stolen deep behind a water cascade somewhere in this world....'<4F>They say among the treasures was the ultimate weapon,the Metal Babble Sword.
; Text $0717: This is the graveyard of our pirate ancestors.'<4F>This graveyard is submerged by water each night,like a man drowning in the sea.
; Text $0718: I hear that long ago this village possessed the Stone of Drought which could stop even the flow of a water cascade.
; Text $0719: My slothful husband! Sleeping is all he does! What's he thinking?
; Text $071A: Being in the trade,my husband knows much about tools.
; Text $071B: Here in Stancia,we have an old legend about Zenithian Castle.'<4F>The scholar at our Castle knows the legend well.
; Text $071C: La,Di,La...Your Beautiful Face,Reflecting On Water...'<4F>Excuse me...EXCUSE ME! We're having a rendezvous.Don't intrude!
; Text $071D: Welcome to Stancia,a waterway town.
; Text $071E: I must cook a meal before my husband returns.
; Text $071F: The Zenithians always look after us.
