; Huffman-compressed text group(s): $39
; Text $0720: I've reached this far searching for the Zenithian Helm.'<4F>I've heard the King here has it.
; Text $0721: Sorry,the eatery only opens at night.
; Text $0722: This is Stancia Castle's entrance.
; Text $0723: I'm here to keep monsters out of the Castle.'<4F>The monsters are getting smarter,so I must watch carefully.
; Text $0724: I want to go to Zenithian Castle.'<4F>Yet I don't think I can find all of the Zenithian weapons and armor.'<4F>I heard,however,the Zenithian Shield was once at Burland Castle....
; Text $0725: In this country,we have an old legend about Zenithian Castle.'<4F>Whoever obtains the Zenithian Armor,Helm,Shield,and Sword will be allowed into Zenithia.'<4F>Only the Helm has been handed down in our royal family.
; Text $0726: If there's really a master of dragons in Zenithian Castle,someone should go ask him...'<4F>to destroy the Ruler of Evil and other monsters.
; Text $0727: My mother used to tell me when I was little...'<4F>there was a castle above the clouds,and the master of dragons lived there.
; Text $0728: They say monsters took over the Castle of the southern country of Santeem.'<4F>I don't blame the King for wanting to laugh away his fears.
; Text $0729: I hate weapons and armor.They're so heavy!'<4F>We must be prepared for the monsters' attack,though.
; Text $072A: To see the King,go up these stairs.
; Text $072B: Everyone here has been gloomy since the monsters appeared.'<4F>That's why the King issued the proclamation even though he knew he would be laughed at.
; Text $072C: What's black and white and red all over? A penguin falling down the stairs! Isn't that funny?
; Text $072D: If you can make the King laugh,you'll receive any reward you want.Go for it!
; Text $072E: The King issued such a strange proclamation.I wonder what he's up to.
; Text $072F: I believe my father had a good reason for his actions,but....
; Text $0730: You are wiping out the monsters? I admire you!
; Text $0731: I'm Pocos.'<4F>You can have a strange dream at my inn! Isn't that exciting?
; Text $0732: Gardenbur Castle is surrounded by rocky mountains.There used to be a cave which led through the mountains.'<4F>A volcanic eruption blocked the cave with lava.'<4F>The Magma Staff might be able to melt a pathway through the mountains....
; Text $0733: Welcome to Gardenbur Castle.
; Text $0734: Only women live in this Castle.Our Queen is a very beautiful woman.
; Text $0735: We guard as well as any men!
; Text $0736: I haven't been able to leave since the volcanic eruption....'<4F>What? A passage is now open? Hmm...should I be happy or what?
; Text $0737: Aha! Travelers!'<4F>A passage must be open now.That's good.
; Text $0738: The rumor is that the Ruler of Evil will resurrect at last.
; Text $0739: The Ruler of Evil must be male.If I'm right,he may have a weakness for girls.
; Text $073A: I prefer a strong man,no matter how he looks.
; Text $073B: This is the Queen's dressing room.'<4F>Don't touch those beautiful dresses with your dirty hands!
; Text $073C: The Queen speaks harshly,but she's actually tender hearted.'<4F>She would have enjoyed a commoner's life if she hadn't been born into the royal family.I feel sorry for her.
; Text $073D: This is an old story.When the Queen's grandmother was young...'<4F>she received something called the Zenithian Shield from Burland's King.
; Text $073E: I'm studying the rumors related to the Ruler of Evil.'<4F>The resurrection of the Ruler of Evil...the prophecy of the maturing Hero who shall defeat him...'<4F>Master Dragon in Zenithia...'<4F>and the baby born to a celestial nymph in Branca....'<4F>I'm beginning to understand the meaning of all these stories....
; Text $073F: Believe me! I haven't stolen any clothes!
