; Huffman-compressed text group(s): $3A
; Text $0740: I can't tell anyone I lost a fight to a woman soldier....
; Text $0741: This is Rosaville where we Dwarves live.
; Text $0742: Some time ago,an old man came and opened a shop.'<4F>Humans sure know how to run a business.
; Text $0743: An elf called Rosa used to live in this village.'<4F>Her teardrops turned into rubies.'<4F>Some humans began treating her badly in order to make her cry all the time.
; Text $0744: Sob...Sob...Poor Rosa.'<4F>If Saro hadn't rescued her,the humans would have devastated her.
; Text $0745: I came here searching for an elf who sheds ruby teardrops.'<4F>I'll be rich if I can capture the elf!
; Text $0746: This is a place for Dwarves and animals.'<4F>You humans are not welcome.Please leave.
; Text $0747: Will the Ruler of Evil destroy us Dwarves if he resurrects? I'm worried....
; Text $0748: Neigh! Don't worry.Saro will take care of it.Neigh!
; Text $0749: Bow,Wow! Saro made me smarter.'<4F>I can speak man's language!
; Text $074A: Meow...Meow...I have to thank Saro.'<4F>The Secret of Evolution is nice!
; Text $074B: Saro made this tower.'<4F>They say he had a secret chamber built somewhere inside it...'<4F>and has been hiding something precious there.
; Text $074C: The world is about to be obliterated by the monsters.'<4F>The ruler of the monsters is Saro.'<4F>He's renamed himself Necrosaro and intends to use the Secret of Evolution to become even more formidable.'<4F>Please,stop Saro...no Necrosaro.'<4F>I don't want him to continue on this evil path...'<4F>even if it means ending his life...Sob...Sob...'<44><49> obtains Ruby Teardrops!<44>However,they crumble silently away....
; Text $074D: This is Dire Palace,the monsters' castle!
; Text $074E: Poor humans! Without wings,they can't fly!'<4F>But I hear they used to fly in things called balloons.
; Text $074F: Necrosaro's been busily traveling all over the world lately.'<4F>The day we take over the world from mankind seems near.
; Text $0750: What are you doing here?'<4F>You'll be late for the meeting.'<4F>Hurry to the meeting room on the second floor.
; Text $0751: Sniff...Sniff...I smell humans....
; Text $0752: Huff...Huff...I'll become thin by running....
; Text $0753: I'm thin so I'll be the last to be eaten.
; Text $0754: I don't care what happens to others!'<4F>As long as I survive!
; Text $0755: What are you doing there? Get in quickly!'<4F>Necrosaro will be here any minute.
; Text $0756: Your seat is behind mine.'<4F>Say hello to everyone,then sit in your seat and be quiet.
; Text $0757: Hmm...could it be possible that the Hero,who we thought we'd destroyed,is alive?
; Text $0758: Maybe the Secret of Evolution is perfected.
; Text $0759: Long ago,Esturk,the Ruler of Evil,reached the final phase of evolution.'<4F>Fearing his formidable power,the celestial master imprisoned him underground.
; Text $075A: Santeem's King is unlucky!'<4F>His dream revealed that men would inadvertently aid Esturk's resurrection...'<4F>and he tried to stop the excavation at Aktemto.That's probably why he was crushed by the evil force.'<4F>Even we monsters didn't guess Esturk was imprisoned there.
; Text $075B: He,He,He! Today's main dish is Human Stew.
; Text $075C: I'm hungry....
; Text $075D: Hmm...I still don't get it.Where does the food go when skeleton monsters eat?
; Text $075E: My co-workers struck upon something extraordinary!'<4F>But monsters suddenly raided the mine and...Cough...Cough...
; Text $075F: Oh,my....The end has come!
