; Huffman-compressed text group(s): $3B
; Text $0760: This is Aktemto,a mining town.Actually,it used to be....You'd better flee!
; Text $0761: Monsters! Monsters are coming! Help!
; Text $0762: Darn! This is a maze! I'm lost....
; Text $0763: Kiii! Have to find Esturk the Great at once.
; Text $0764: Finally! I've struck upon a hoard of treasure! Gasp!
; Text $0765: We're Esturk the Great's servants.We've lived for eons.'<4F>He made us immortal.'<4F>As long as he lives,so shall we!
; Text $0766: Welcome to Riverton,a riverside town.
; Text $0767: Long ago,men flew in vessels.'<4F>It's said the Ruler of Evil stole the essential component of the vessels.'<4F>It was probably buried along with him.
; Text $0768: I saw it!'<4F>The giant statue upstream walked!
; Text $0769: They say the monsters' castle is on this island.'<4F>No one has ever returned from the castle.
; Text $076A: <4E>No response.<43>No one seems to be in.
; Text $076B: My husband doesn't listen to my stories.
; Text $076C: This is Gottside,the closest town to Zenithia.
; Text $076D: Esturk who came back to life was destroyed by the Hero as prophesied.'<4F>But the next Esturk is about to be born!
; Text $076E: It's an awful thing!'<4F>They say the monster called Necrosaro has perfected the Secret of Evolution.
; Text $076F: According to rumors,Necrosaro began using the Secret of Evolution deep underground.
; Text $0770: I'm afraid!'<4F>With the Golden Bracelet,the Secret of Evolution will be even more devastating than before.
; Text $0771: I know it.'<4F>Only hatred drives Necrosaro now.'<4F>Unless stopped now,he'll evolve into the most horrible being.
; Text $0772: I'm a prophet.'<4F>The prophesy that Esturk would come back to life and be destroyed by the Hero was true.'<4F>But I know of no prophesy for the future thereafter.
; Text $0773: I hear that somewhere on this island there's a tower leading to Zenithia.
; Text $0774: Not everyone who climbs the tower to Zenithia can enter Zenithia.'<4F>It's said only those who possess all of the Zenithian weapons and armor can enter....
; Text $0775: The person sleeping there fell down from the sky.
; Text $0776: This is the closest island to Zenithia.'<4F>But it's also close to the world of darkness.'<4F>There's a formidably perilous cave on the west side of this island.
; Text $0777: <4E>No one is inside.
; Text $0778: This is Elfville.
; Text $0779: Monsters began living in the world tree.
; Text $077A: Bark,Bark! The giant tree in this village is a world tree.
; Text $077B: This world tree has many leaves.'<4F>You will find the leaves very useful.
; Text $077C: You're embarking on a difficult journey,aren't you?'<4F>I called your wagon here with the Baron's Horn.
; Text $077D: Crackle...Crackle....Don't proceed any further!
; Text $077E: It's been ages since the last time I saw humans!'<4F>You must watch out!'<4F>They say long ago the Ruler of Evil's palace existed somewhere around here.
; Text $077F: I'm searching for the Zenithian Armor.'<4F>I suspect it's in the nearby cave.
