; Huffman-compressed text group(s): $3C
; Text $0780: It's said that the great ones catch teardrops in their hands.'<4F>Journey carefully.
; Text $0781: Soretta Castle is in the far south.
; Text $0782: You're going to embark on a dangerous journey,right?'<4F>I called your wagon by using the Baron's Horn.
; Text $0783: Creeek...Creeek...
; Text $0784: I'm guarding the treasure under Balzack's order.Leave immediately! Crackle...Crackle...
; Text $0785: Welcome back,Ragnar! I see you haven't progressed much.'<4F>You must find the cause of the disappearances at once.'<44>
; Text $0786: Welcome back,Ragnar!'<4F>I can see you've found something.'<4F>Hmm...Flying Shoes? I see....'<4F>Anyway...rescue the children at once.'<44>
; Text $0787: A splendid castle,always....'<4F>I wish to be a royal soldier.Say...can you take me along?
; Text $0788: Really!? I shall follow you then.
; Text $0789: Gasp...Gasp...too tough for an old man.Go on alone,please.
; Text $078A: I understand.Sorry I bothered you.
; Text $078B: Want to buy something? If so,go outside and talk to me from across the counter.
; Text $078C: Ragnar,did you know?'<4F>Some doors aren't locked.They open without a key.
; Text $078D: I'm Flora.My husband,Alex,hasn't returned from his last trip.'<4F>Tell me if you see him!
; Text $078E: What? Alex is in Izmit Village? Caught stealing?'<4F>Take me there,please!
; Text $078F: Alex will return,won't he?
; Text $0790: Ragnar,I'm on my way to Izmit Village too.
; Text $0791: I'm in trouble...I'm lost....
; Text $0792: What? You can take me to the exit? No thanks! I can find the way out myself!
; Text $0793: I'm Healie.I'm a Healer,but I dream of becoming human.'<4F>If I make friends with humans,perhaps I'll become one.Take me along.
; Text $0794: Hurray! Thanks!'<44><4E>Healie joined the Party!<43><55><40>
; Text $0795: No? If you change your mind,come back again,OK?
; Text $0796: Hmm...is that so? Very well!'<4F>I'll go tell the King about the Ruler of Evil and the Hero.'<4F>Return these children to their mothers.Farewell!
; Text $0797: Oh,Ragnar! I found the old well by chance and came this far.'<4F>The monsters in this tower are very tough!'<4F>I should have let Healie whom I met in the well join me.
; Text $0798: <4E><44>'I envy you.'
; Text $0799: <4E><44>Ragnar remembers his comrade's words.
; Text $079A: Ra...Ragnar...I'm nearing my end....Listen well....
; Text $079B: <4E><44>'Somewhere in this world,the Ruler of Evil is about to resurrect.'<4F>Also,according to a prophecy,the Hero who shall defeat him is now growing up.'<4F>The evil ones intend to destroy the Hero while he or she is growing and still weak.'<4F>Ragnar,save all children....
; Text $079C: You fool! As you wish,I'll smash you to bits.
; Text $079D: Ragnar! Good work.Say...'<4F>will you let me take credit for saving the children?
; Text $079E: I was only kidding.You're so naive.
; Text $079F: What? You already saved the children? Yeaaaah!
