; Huffman-compressed text group(s): $3D
; Text $07A0: What's wrong,Alena? You still insist on going out?
; Text $07A1: Never! Why are you so reckless?
; Text $07A2: Good,you understand! That's more like it.You can go to your room,now.
; Text $07A3: You returned,Alena!'<4F>You don't have to explain.I know you'll go out again even if I try to stop you.'<4F>Remember one thing,though.Never venture into lands where I can't look out for you.
; Text $07A4: Oh,Alena! How tragic....I feared this would happen....
; Text $07A5: The King only says these things because he is concerned about you.Please understand.
; Text $07A6: Thank goodness.You returned safely.
; Text $07A7: Oh,no.Princess....We must revive her at any cost.
; Text $07A8: This is Santeem Castle.
; Text $07A9: The chambers of the King and the Princess are upstairs.
; Text $07AA: <4E>Brey:'Princess! Why are you such a tomboy?'<44>Brey:'Your late mother was so refined.'<44>Brey:'As your tutor I feel responsible for how you've turned out.'
; Text $07AB: Her reckless acts shame us.'<4F>Oops,Princess!? Excuse me....
; Text $07AC: Oh,Princess...! How terrible....
; Text $07AD: The King is already asleep.
; Text $07AE: Oh,Princess.I'm fixing the wall.Can you wait awhile?
; Text $07AF: I requested that the wall in the Princess' chamber be fixed.
; Text $07B0: <4E><44>'Don't ever kick the wall again,please.'
; Text $07B1: By the King's order,I can't let you pass.
; Text $07B2: Please return to your chamber.
; Text $07B3: Ah,Princess! You look well.
; Text $07B4: The King moans late at night.I wonder if he's having nightmares....
; Text $07B5: Welcome to Surene Town.
; Text $07B6: My fellow merchants said the Princess left on a journey.Oops! That's supposed be a secret.OK?
; Text $07B7: I'm Marone the poet.'<4F>Blue Sky,Wandering Clouds,La,La,La...
; Text $07B8: Shining Crescent,Glittering Stars,La,La,La...
; Text $07B9: Marone's songs are always lovely!
; Text $07BA: Go north then east.You'll find a small mountain village.
; Text $07BB: I fell in love with her.I wish she'd marry me.
; Text $07BC: I'm sorry.I can't.I'm too old for you.
; Text $07BD: Hmm...you're a woman,yet you've embarked on a dangerous journey.'<4F>I recommend you build your strength around this town first.
; Text $07BE: I hear singing.I think I'll sleep soundly.
; Text $07BF: That Marone! He's lucky.'<4F>I wish I could sing like him....
