; Huffman-compressed text group(s): $3E
; Text $07C0: The chief's daughter,Nina,is to be offered.'<4F>My son was going to marry her....
; Text $07C1: No! I won't let them offer you.If we run away....
; Text $07C2: I must offer my daughter,Nina,to save the village.'<4F>Isn't there anyone strong enough to put an end to the monster?
; Text $07C3: Oh! You will?'<4F>If that's true,please go see the shaman!
; Text $07C4: I understand....
; Text $07C5: You plan to destroy the monster? It only appears when given offerings.'<4F>Are you willing to be given as an offering?
; Text $07C6: You are? Please wait awhile.The offering litter will arrive soon.
; Text $07C7: No one wants to die.By the way...'<44>
; Text $07C8: Please be careful.
; Text $07C9: Everyone appreciates what you've done.Anyway...'<44>
; Text $07CA: This is Frenor.The Princess of Santeem is here.I'll go see her.
; Text $07CB: You came to see the Princess? She's upstairs in the inn.
; Text $07CC: I wonder why the Princess is here.
; Text $07CD: I wish to get acquainted with the Princess.
; Text $07CE: Since she's a princess,I thought she'd be prettier.
; Text $07CF: Welcome to our inn...'<4F>however,a princess is staying here,so I can't really welcome you....
; Text $07D0: Do you know where my dog is?
; Text $07D1: My goodness! The Princess was kidnapped!
; Text $07D2: Why was she kidnapped?
; Text $07D3: I hope she's alright.
; Text $07D4: Any princess would be an attractive target for the wicked.
; Text $07D5: Weep...'<44>
; Text $07D6: My dog,Kit,brought this letter.I'll read it.'<4F>To get the Princess back unharmed,bring the village treasure,the Golden Bracelet,to the graveyard tomorrow night.'<4F>What's this?
; Text $07D7: The Princess was a fake.I knew a real princess wouldn't come to a town like this.
; Text $07D8: By the way,a bazaar is held at an oasis in the southern desert.'<4F>If you're heading south,you should visit it.
; Text $07D9: I offered my savings to the Princess...'<4F>but she refused.They say she was a fake,but she wasn't a crook.
; Text $07DA: A bazaar is held in the southern desert,right?
; Text $07DB: You gave the Golden Bracelet to the kidnappers.Hmm....'<4F>I hope nothing bad will happen.
; Text $07DC: I can't sleep.On nights like this,I remember my old days.'<4F>I used to live in an eastern town of Endor.I often went to the tournament.
; Text $07DD: Oh,<49>! How's the King? I've been very worried....
; Text $07DE: Sorry,we're closed for today.
; Text $07DF: Birdsong Nectar? This shop once had some.'<4F>You might get some in the western tower where they say elves visit.
Bank03_TextGroup_3E:
