; Huffman-compressed text group(s): $3F
; Text $07E0: This is the Travel Door to Endor.'<4F>The King told me not to let the Princess pass.
; Text $07E1: The messenger delivered the King's permission.You can pass now.
; Text $07E2: ..................'
; Text $07E3: How terrible! He can't speak!'<4F>This must be kept a secret,but if he remains like this....'<4F>Yes,I know! Goz,the old man who lives in the backyard shed,may know a remedy.
; Text $07E4: The King keeps peace in this country.Don't let others know.
; Text $07E5: The King hasn't spoken to me in a while.Is anything wrong?
; Text $07E6: The King lost his voice!?'<4F>I know Marone,the poet,damaged his throat once.'<4F>Now he has the loveliest voice in the country.He may know what to do.
; Text $07E7: Yes,I'm Marone.Why is my voice so lovely?'<4F>I think taking Birdsong Nectar,an elfin medicine,helped.'<4F>I found it in a desert bazaar during a trip.La,La,La...
; Text $07E8: Continue your journey safely.'<4F>I'll think about the dreams I had.'<4F>I think I had another dream besides those nightmares,but I can't remember it....
; Text $07E9: How fortunate! The dreams the King had worry me,however....
; Text $07EA: The King has spoken to me.What a lovely voice he has!
; Text $07EB: This is the country of Endor.The Castle is in the east.
; Text $07EC: Guarding is hard.
; Text $07ED: How delicious!
; Text $07EE: It's tough to create a menu every night.
; Text $07EF: You're here for the tournament too? I believe...'<4F>the King has a motive for attracting the strong in this way.
; Text $07F0: My daughter is always looking at the sky these days.What's got into her?
; Text $07F1: Have you been to the underground casino? I won today!
; Text $07F2: I dedicate to you this song of glory...An Iron Claw on the Right Hand,La,La,La...
; Text $07F3: Sss...Sss...
; Text $07F4: Grzz...Grzz...there! Necrosaro! Mumble...Mumble...
; Text $07F5: A fighter called Necrosaro is advancing in the tournament.What a malevolent name....
; Text $07F6: This is a poker table.Would you like to play?
; Text $07F7: Drop by any time.
; Text $07F8: Welcome! The King of Santeem told me about you.'<4F>I admire that you're concerned over this doomed world and are embarking on a journey to prove your strength!'<4F>I have a request.Win the tournament.'<4F>To tell the truth,I'm regretting what I've promised....
; Text $07F9: <4E><44>'<49>,please revive Princess Alena at once!'
; Text $07FA: My father proclaimed that the tournament's winner will marry me.'<4F>If the winner is a woman,I won't be required to marry.'<4F>Please enter and win the tournament.
; Text $07FB: <4E><44>'Princess Alena,I envy you for being so free.'
; Text $07FC: The King has made a terrible promise.Would you listen to the Princess' story?
; Text $07FD: To enter the Castle at night,you must evade sentries.
; Text $07FE: Only those registered can enter the tournament.Obtain permission from the King
; Text $07FF: The King has given only Princess Alena permission to enter.However,you're not properly equipped.
Bank03_TextGroup_3F:
