; Huffman-compressed text group(s): $40
; Text $0800: Princess Alena.The best of luck to you.
; Text $0801: Thanks to you,I won't have to marry someone I despise.'<4F>If Princess Alena was a man...'<4F>What am I saying...please forget what I've said.
; Text $0802: How strong Princess Alena is! I'm impressed.
; Text $0803: Now the tournament is over,the Coliseum is closed.
; Text $0804: After Necrosaro vanished,monsters stopped appearing.
; Text $0805: Necrosaro...vanished,a mysterious man.
; Text $0806: Congratulations on your victory!
; Text $0807: I'm happy for the Princess.
; Text $0808: Isn't there anyone who wants to buy my shop and do business here?
; Text $0809: Oh,you're Princess Alena!'<4F>You've been the talk of us merchants.
; Text $080A: <4E>Neta:'Go out and head west.Don't be a sleepy-head.Have a nice day.'
; Text $080B: <4E>Neta:'You're back.Are you tired?'<44>
; Text $080C: <4E>Neta:'Rest well.Good night.'
; Text $080D: <4E>Neta:'Wake up,darling.It's morning.'
; Text $080E: <4E><44>Neta:'Here's your lunch.Have a good day.'
; Text $080F: <4E>Neta:'I hope we have our own shop someday.'<44>Neta:'You're not the type to work for others forever.'<44>Neta:'That's why I married you.Of course that wasn't the only reason...Tee,Hee...'
; Text $0810: <4E>Neta:'Forgot something? Work hard...smack!'
; Text $0811: <4E>Neta:'Welcome home.You worked late today.'<44>
; Text $0812: Grandpa Tom wishes everyday for his vagabond son's safe return.
; Text $0813: Welcome to the Town of Lakanaba.
; Text $0814: <4E><44>'Oh,it's you,Taloon.I didn't have to greet you!'
; Text $0815: <4E>Tom:'Taloon,I'm old and my limbs are getting weak.'<44>
; Text $0816: <4E>Tom:'I'll pay you to take me to the House of Healing.Will you?'
; Text $0817: <4E>Tom:'Push me!'
; Text $0818: <4E>Tom:'That's too bad.'
; Text $0819: <4E>Tom:'Come on,son.You can push better than that!'
; Text $081A: <4E>Tom:'I'm finally at the House of Healing.Thanks so much.Here's your reward!'<44>Taloon received <47> gold piece<4C>.
; Text $081B: <4E>Tom:'My son was a fool to leave the town.He never writes.'<44>Tom:'I wonder what he's doing?'
; Text $081C: Taloon,have you heard of the Iron Safe?
; Text $081D: You'd better get the Iron Safe before you go south.
; Text $081E: A guest said the Iron Safe might be in a northern cave.'<4F>I also heard it should protect your money even when you're defeated by monsters.
; Text $081F: Work hard and soon you might own a shop like mine.
